using System.ComponentModel;
using System.Net;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;

// --- Configuration ---

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- DI & services ---

var services = new ServiceCollection();
services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

services.AddChatClient(builder =>
    builder.UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();
var loggerFactory = sp.GetRequiredService<ILoggerFactory>();

// --- Tools ---

var notepad = new Notepad();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        ([Description("The search query to look up on the web")] string query) =>
        {
            return WebSearcher.SearchAsync(query);
        },
        "web_search",
        "Searches the web for information on a given query. Returns a list of result snippets."),

    AIFunctionFactory.Create(
        ([Description("The title or key for this note")] string title,
         [Description("The content to save")] string content) =>
        {
            notepad.Save(title, content);
            return $"Note saved: \"{title}\"";
        },
        "save_note",
        "Saves a research note with a title and content for later reference."),

    AIFunctionFactory.Create(
        () => notepad.GetAll(),
        "get_notes",
        "Retrieves all previously saved research notes."),
};

// --- Agent ---

var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    instructions: """
        You are a research assistant. When given a topic:
        1. Use web_search to find relevant information (make 2-3 searches with different queries).
        2. Use save_note to record key findings from each search.
        3. Use get_notes to review everything you've collected.
        4. Provide a well-structured summary with sections and key takeaways.
        Always cite your sources. Be thorough but concise.
        """,
    description: "An AI agent that researches topics by searching the web and taking notes.",
    tools: tools,
    loggerFactory: loggerFactory);

// --- Run ---

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent (MAF)        ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

string topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptUser();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var session = await agent.CreateSessionAsync();
var runOptions = new ChatClientAgentRunOptions(
    new ChatOptions { Temperature = 0f, MaxOutputTokens = 2048 });

await foreach (var update in agent.RunStreamingAsync(
    topic, session, runOptions, CancellationToken.None))
{
    if (update.Text is { } text)
    {
        Console.Write(text);
    }
}

Console.WriteLine("\n\n✅ Research complete.");

// --- Helpers ---

static string PromptUser()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input)
        ? "Latest advances in quantum computing 2025"
        : input;
}

// --- Web Search Tool Implementation ---

internal static class WebSearcher
{
    private static readonly HttpClient Http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html" },
        },
    };

    /// <summary>
    /// Performs a web search by querying a search engine and extracting snippets.
    /// Falls back to a direct fetch if search fails.
    /// </summary>
    public static async Task<string> SearchAsync(string query)
    {
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";
            var html = await Http.GetStringAsync(url);

            var snippets = ExtractSnippets(html);
            if (snippets.Count == 0)
            {
                return $"Search for \"{query}\" returned no usable results. Try rephrasing.";
            }

            return $"Search results for \"{query}\":\n" +
                   string.Join("\n", snippets.Select((s, i) => $"  {i + 1}. {s}"));
        }
        catch (Exception ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}";
        }
    }

    private static List<string> ExtractSnippets(string html)
    {
        var snippets = new List<string>();

        // Extract text between <td> tags in the results table (DuckDuckGo Lite format)
        var spans = html.Split(["<td class=\"result-snippet\">", "<td>"], StringSplitOptions.None);
        foreach (var span in spans.Skip(1))
        {
            var endIdx = span.IndexOf("</td>", StringComparison.OrdinalIgnoreCase);
            if (endIdx <= 0) continue;

            var text = StripHtml(span[..endIdx]).Trim();
            if (text.Length > 30 && !text.StartsWith('<'))
            {
                snippets.Add(text.Length > 300 ? text[..300] + "..." : text);
            }

            if (snippets.Count >= 6) break;
        }

        return snippets;
    }

    private static string StripHtml(string html) =>
        System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", " ")
            .Replace("&amp;", "&")
            .Replace("&lt;", "<")
            .Replace("&gt;", ">")
            .Replace("&quot;", "\"")
            .Replace("&#x27;", "'")
            .Replace("  ", " ")
            .Trim();
}

// --- Notepad Tool Implementation ---

internal sealed class Notepad
{
    private readonly Dictionary<string, string> _notes = new(StringComparer.OrdinalIgnoreCase);

    public void Save(string title, string content) => _notes[title] = content;

    public string GetAll()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n", _notes.Select(kv =>
            $"📝 {kv.Key}\n{kv.Value}"));
    }
}

